@Injectable()
export class AuditService implements IAuditService {
  constructor(@Inject(DB_CLIENT) private readonly db: Kysely<Database>) {}

  async log(params: AuditEntryDto): Promise<void> {
    try {
      await this.db
        .insertInto('audit_log')
        .values({
          id: crypto.randomUUID(),
