@Injectable()
export class InventoryCountRepository implements IInventoryCountRepository {
  constructor(@Inject(DB_CLIENT) private readonly db: Kysely<Database>) {}

  private mapBatch(row: any): InventoryCountBatch {
    return {
      id: asCountBatchId(row.id),
      restaurantId: asRestaurantId(row.restaurant_id),
      status: row.status as 'OPEN' | 'CLOSED',
      snapshotTimestamp: row.snapshot_timestamp,
      version: row.version,
      createdAt: row.created_at,
      updatedAt: row.updated_at
    };
  }

  private mapRow(row: any): InventoryCountRow {
    return {
      id: asCountRowId(row.id),
      batchId: asCountBatchId(row.batch_id),
      itemId: asItemId(row.item_id),
      expectedQty: row.expected_qty,
      actualQty: row.actual_qty
    } as InventoryCountRow;
  }

  async createBatch(db: any, restaurantId: RestaurantId): Promise<InventoryCountBatch> {
    const trx = db as Kysely<Database>;
    const id = asCountBatchId(randomUUID());
    const row = await trx
      .insertInto('inventory_count_batches')
      .values({
        id,
        restaurant_id: restaurantId,
        status: 'OPEN',
        snapshot_timestamp: new Date().toISOString()
      })
      .returningAll()
      .executeTakeFirstOrThrow();

    return this.mapBatch(row);
  }

  async findBatchById(batchId: CountBatchId): Promise<InventoryCountBatch | null> {
    const row = await this.db
      .selectFrom('inventory_count_batches')
      .selectAll()
      .where('id', '=', batchId)
      .executeTakeFirst();

    return row ? this.mapBatch(row) : null;
  }

  async listBatches(restaurantId: RestaurantId, limit: number = 50, offset: number = 0): Promise<InventoryCountBatch[]> {
    const rows = await this.db
      .selectFrom('inventory_count_batches')
      .selectAll()
      .where('restaurant_id', '=', restaurantId)
      .orderBy('created_at', 'desc')
      .limit(limit)
      .offset(offset)
      .execute();

    return rows.map(r => this.mapBatch(r));
  }

  async updateBatchStatus(
    trx: any,
    batchId: CountBatchId,
    status: string,
    version: number,
  ): Promise<boolean> {
    const db = trx as Kysely<Database>;
    const res = await db
      .updateTable('inventory_count_batches')
      .set({ 
        status: status as 'OPEN' | 'CLOSED', 
        version: version + 1,
        updated_at: new Date().toISOString()
      })
      .where('id', '=', batchId)
      .where('version', '=', version)
      .executeTakeFirst();

    return res.numUpdatedRows > 0n;
  }

  async findRowsByBatchId(batchId: CountBatchId): Promise<InventoryCountRow[]> {
    const rows = await this.db
      .selectFrom('inventory_count_rows')
      .selectAll()
      .where('batch_id', '=', batchId)
      .execute();

    return rows.map(r => this.mapRow(r));
  }

  async updateCountRow(
    db: any,
    rowId: CountRowId,
    actualQty: number,
  ): Promise<InventoryCountRow> {
    const trx = db as Kysely<Database>;
    const row = await trx
      .updateTable('inventory_count_rows')
      .set({ 
        actual_qty: actualQty
      })
      .where('id', '=', rowId)
      .returningAll()
      .executeTakeFirstOrThrow();

    return this.mapRow(row);
  }

  async createCountRows(
    db: any,
    batchId: CountBatchId,
    rows: CreateCountRowInput[],
  ): Promise<void> {
    const trx = db as Kysely<Database>;
    if (rows.length === 0) return;

    await trx
      .insertInto('inventory_count_rows')
      .values(rows.map(r => ({
        id: asCountRowId(randomUUID()),
        batch_id: batchId,
        item_id: asItemId(r.item_id),
        expected_qty: r.expected_qty,
        actual_qty: null,
        variance_qty: null
      })))
      .execute();
  }
}

import { DB_CLIENT } from '../core/core.symbols';
import { Injectable, Inject } from '@nestjs/common';
import { Kysely } from 'kysely';
import { randomUUID } from 'crypto';
import { Database, RestaurantId, ItemId, StockLevel, asItemId } from '@ims/types';
import { ILedgerRepository } from './interfaces/i-ledger.repository';

@Injectable()
export class LedgerRepository implements ILedgerRepository {
  constructor(@Inject(DB_CLIENT) private readonly db: Kysely<Database>) {}

  async insertEntry(trx: unknown, entry: Record<string, unknown>): Promise<void> {
    const db = trx as Kysely<Database>;
    await db
      .insertInto('inventory_ledger')
      .values({
        id: randomUUID() as import('@ims/types').LedgerEntryId,
        restaurant_id: entry.restaurant_id as RestaurantId,
        item_id: entry.item_id as ItemId,
        change_amount: entry.change_amount as number,
        reason_code: entry.reason_code as import('@ims/types').LedgerReasonCode,
        reference_id: (entry.reference_id as string | undefined) ?? null,
      })
      .execute();
  }

  async sumChangeAmount(restaurantId: RestaurantId, itemId: ItemId): Promise<number> {
    const result = await this.db
      .selectFrom('inventory_ledger')
      .select(({ fn }) => [
        fn.sum<number>('change_amount').as('total')
      ])
      .where('restaurant_id', '=', restaurantId)
      .where('item_id', '=', itemId)
      .executeTakeFirst();

    return Number(result?.total || 0);
  }

  async sumChangeAmountBulk(restaurantId: RestaurantId): Promise<any[]> {
    const results = await this.db
      .selectFrom('inventory_ledger as il')
      .select([
        'il.item_id',
        ({ fn }) => fn.sum<number>('il.change_amount').as('total')
      ])
      .where('il.restaurant_id', '=', restaurantId)
      .groupBy(['il.item_id'])
      .execute();

    return results.map(r => ({
      itemId: asItemId(r.item_id),
      qty: Number(r.total || 0)
    }));
  }

  async getLedgerEntries(restaurantId: RestaurantId, limit: number, offset: number): Promise<any[]> {
    return await this.db
      .selectFrom('inventory_ledger as il')
      .select([
        'il.id',
        'il.created_at',
        'il.reason_code',
        'il.change_amount',
        'il.reference_id',
        'il.item_id'
      ])
      .where('il.restaurant_id', '=', restaurantId)
      .orderBy('il.created_at', 'desc')
      .limit(limit)
      .offset(offset)
      .execute();
  }
