@Injectable()
export class ItemRepository implements IItemRepository {
  constructor(@Inject(DB_CLIENT) private readonly db: Kysely<Database>) {}

  async findById(itemId: ItemId, restaurantId: RestaurantId): Promise<ItemWithOverride | null> {
    const item = await this.db
      .selectFrom('items')
      .leftJoin('item_restaurant_overrides', (join) =>
        join.onRef('item_restaurant_overrides.item_id', '=', 'items.id')
            .on('item_restaurant_overrides.restaurant_id', '=', sql`${restaurantId}`)
      )
      .select([
        'items.id as id',
        'items.franchise_group_id as franchiseGroupId',
        'items.restaurant_id as itemRestaurantId',
        'items.category_id as categoryId',
        'items.name as name',
        'items.sku as sku',
        'items.type as type',
        'items.purchasing_uom as purchasingUom',
        'items.inventory_uom as inventoryUom',
        'items.recipe_uom as recipeUom',
        'items.inv_to_recipe_ratio as invToRecipeRatio',
        'items.is_active as itemIsActive',
        'items.created_at as itemCreatedAt',
        'items.updated_at as itemUpdatedAt',
        'items.allergens as itemAllergens',
        'items.calories_per_uom as itemCaloriesPerUom',
        'items.protein_grams as itemProteinGrams',
        'items.fat_grams as itemFatGrams',
        'items.carbs_grams as itemCarbsGrams',
        'item_restaurant_overrides.id as overrideId',
        'item_restaurant_overrides.par_level as overrideParLevel',
        'item_restaurant_overrides.is_active as overrideIsActive',
      ])
      .where('items.id', '=', itemId)
      .executeTakeFirst();

    if (!item) {
      return null;
    }

    const hasOverride = item.overrideId != null;

    const result: ItemWithOverride = {
      id: asItemId(item.id as string),
      franchiseGroupId: item.franchiseGroupId ? asFranchiseGroupId(item.franchiseGroupId as string) : null,
      restaurantId: item.itemRestaurantId ? asRestaurantId(item.itemRestaurantId as string) : null,
      categoryId: asCategoryId(item.categoryId as string),
      name: item.name as string,
      sku: item.sku as string,
        type: item.type as import('@ims/types').ItemType,
      purchasingUom: item.purchasingUom as string,
      inventoryUom: item.inventoryUom as string,
      recipeUom: item.recipeUom,
      invToRecipeRatio: Number(item.invToRecipeRatio),
      isActive: Boolean(item.itemIsActive),
      createdAt: item.itemCreatedAt as string,
      updatedAt: item.itemUpdatedAt as string,
      ...(hasOverride
        ? {
            override: {
              id: item.overrideId as string,
              itemId: asItemId(item.id as string),
              restaurantId: restaurantId,
              parLevel: Number(item.overrideParLevel),
              isActive: Boolean(item.overrideIsActive),
              createdAt: item.itemUpdatedAt as string,
              updatedAt: item.itemUpdatedAt as string,
            }
          }
        : {}),
      effectiveParLevel: hasOverride ? Number(item.overrideParLevel) : 0,
      effectiveIsActive: hasOverride ? Boolean(item.overrideIsActive) : Boolean(item.itemIsActive),
      allergens: Array.isArray(item.itemAllergens) ? item.itemAllergens : [],
      caloriesPerUom: Number(item.itemCaloriesPerUom || 0),
      proteinGrams: Number(item.itemProteinGrams || 0),
      fatGrams: Number(item.itemFatGrams || 0),
      carbsGrams: Number(item.itemCarbsGrams || 0),
    };

    return result;
  }

  async getUomConversion(itemId: ItemId, fromUom: string, toUom: string): Promise<UomConversion | null> {
    const conversion = await this.db
      .selectFrom('uom_conversions')
      .selectAll()
      .where('item_id', '=', itemId)
      .where('from_uom', '=', fromUom)
      .where('to_uom', '=', toUom)
      .executeTakeFirst();

    if (!conversion) return null;

    return {
      id: conversion.id,
      itemId: asItemId(conversion.item_id as string),
      fromUom: conversion.from_uom,
      toUom: conversion.to_uom,
      multiplierFactor: Number(conversion.multiplier_factor),
      createdAt: conversion.created_at as string,
      updatedAt: conversion.updated_at as string,
    };
  }

  async listParLevels(restaurantId: RestaurantId, page = 1, limit = 50): Promise<{ data: ItemWithOverride[]; meta: { total: number; page: number; limit: number; totalPages: number } }> {
    const offset = (page - 1) * limit;

    const [{ count }] = await this.db
      .selectFrom('items')
      .select(({ fn }) => fn.count<number>('id').as('count'))
      .execute();

    const total = Number(count);
    const totalPages = Math.ceil(total / limit);

    const rawItems = await this.db
      .selectFrom('items')
      .leftJoin('item_restaurant_overrides', (join) =>
        join.onRef('item_restaurant_overrides.item_id', '=', 'items.id')
            .on('item_restaurant_overrides.restaurant_id', '=', sql`${restaurantId}`)
      )
      .leftJoin('categories', 'categories.id', 'items.category_id')
      .select([
        'items.id as id',
        'items.franchise_group_id as franchiseGroupId',
        'items.restaurant_id as itemRestaurantId',
        'items.category_id as categoryId',
        'categories.name as categoryName',
        'items.name as name',
        'items.sku as sku',
        'items.type as type',
        'items.purchasing_uom as purchasingUom',
        'items.inventory_uom as inventoryUom',
        'items.recipe_uom as recipeUom',
        'items.inv_to_recipe_ratio as invToRecipeRatio',
        'items.is_active as itemIsActive',
        'items.created_at as itemCreatedAt',
        'items.updated_at as itemUpdatedAt',
        'items.allergens as itemAllergens',
        'items.calories_per_uom as itemCaloriesPerUom',
        'items.protein_grams as itemProteinGrams',
        'items.fat_grams as itemFatGrams',
        'items.carbs_grams as itemCarbsGrams',
        'item_restaurant_overrides.id as overrideId',
        'item_restaurant_overrides.par_level as overrideParLevel',
        'item_restaurant_overrides.is_active as overrideIsActive',
      ])
      .limit(limit)
      .offset(offset)
      .execute();

    const data = rawItems.map((item) => {
      const hasOverride = item.overrideId != null;
      return {
        id: asItemId(item.id as string),
        franchiseGroupId: item.franchiseGroupId ? asFranchiseGroupId(item.franchiseGroupId as string) : null,
        restaurantId: item.itemRestaurantId ? asRestaurantId(item.itemRestaurantId as string) : null,
        categoryId: asCategoryId(item.categoryId as string),
        categoryName: item.categoryName as string | undefined,
        name: item.name as string,
        sku: item.sku as string,
      type: item.type as import('@ims/types').ItemType,
        purchasingUom: item.purchasingUom as string,
        inventoryUom: item.inventoryUom as string,
        recipeUom: item.recipeUom as string,
        invToRecipeRatio: Number(item.invToRecipeRatio),
        isActive: Boolean(item.itemIsActive),
        createdAt: item.itemCreatedAt as string,
        updatedAt: item.itemUpdatedAt as string,
      ...(hasOverride
        ? {
            override: {
              id: item.overrideId as string,
              itemId: asItemId(item.id as string),
              restaurantId: restaurantId,
              parLevel: Number(item.overrideParLevel),
              isActive: Boolean(item.overrideIsActive),
              createdAt: item.itemUpdatedAt as string,
              updatedAt: item.itemUpdatedAt as string,
            }
          }
        : {}),
        effectiveParLevel: hasOverride ? Number(item.overrideParLevel) : 0,
        effectiveIsActive: hasOverride ? Boolean(item.overrideIsActive) : Boolean(item.itemIsActive),
      allergens: Array.isArray(item.itemAllergens) ? item.itemAllergens : [],
      caloriesPerUom: Number(item.itemCaloriesPerUom || 0),
      proteinGrams: Number(item.itemProteinGrams || 0),
      fatGrams: Number(item.itemFatGrams || 0),
      carbsGrams: Number(item.itemCarbsGrams || 0),
      };
    });

    return {
      data,
      meta: { total, page, limit, totalPages }
    };
  }

  async listCategories(restaurantId: RestaurantId, franchiseGroupId: string | null): Promise<Category[]> {
    const categories = await this.db
      .selectFrom('categories')
      .selectAll()
      .where((eb) => {
        const conditions = [
          eb('restaurant_id', '=', restaurantId),
          eb.and([
            eb('restaurant_id', 'is', null),
            eb('franchise_group_id', 'is', null)
          ])
        ];

        if (franchiseGroupId) {
          conditions.push(eb('franchise_group_id', '=', asFranchiseGroupId(franchiseGroupId)));
        }

        return eb.or(conditions);
      })
      .orderBy('name', 'asc')
      .execute();

    return categories.map(c => this.mapCategoryRecord(c));
  }

  async createItem(data: CreateItemCommand): Promise<Item> {
    const [item] = await this.db
      .insertInto('items')
      .values({
        id: uuidv4() as ItemId,
        franchise_group_id: data.franchiseGroupId ? asFranchiseGroupId(data.franchiseGroupId) : null,
        restaurant_id: data.restaurantId ? asRestaurantId(data.restaurantId) : null,
        category_id: asCategoryId(data.categoryId),
        name: data.name,
        sku: data.sku,
        type: data.type,
        purchasing_uom: data.purchasingUom,
        inventory_uom: data.inventoryUom,
        recipe_uom: data.recipeUom ?? null,
        inv_to_recipe_ratio: data.invToRecipeRatio,
        is_active: data.isActive,
        allergens: data.allergens ?? [],
        calories_per_uom: data.caloriesPerUom ?? 0,
        protein_grams: data.proteinGrams ?? 0,
        fat_grams: data.fatGrams ?? 0,
        carbs_grams: data.carbsGrams ?? 0,
      })
      .returningAll()
      .execute();

    if (!item) throw new Error('Failed to create item');
    return this.mapItemRecord(item);
  }

  async updateItem(itemId: ItemId, data: UpdateItemDto, trx?: unknown): Promise<Item> {
    const updateData: Record<string, unknown> = {};
    if (data.categoryId !== undefined) updateData.category_id = data.categoryId;
    if (data.name !== undefined) updateData.name = data.name;
    if (data.sku !== undefined) updateData.sku = data.sku;
    if (data.type !== undefined) updateData.type = data.type;
    if (data.purchasingUom !== undefined) updateData.purchasing_uom = data.purchasingUom;
    if (data.inventoryUom !== undefined) updateData.inventory_uom = data.inventoryUom;
    if (data.recipeUom !== undefined) updateData.recipe_uom = data.recipeUom;
    if (data.invToRecipeRatio !== undefined) updateData.inv_to_recipe_ratio = data.invToRecipeRatio;
    if (data.isActive !== undefined) updateData.is_active = data.isActive;
    if (data.allergens !== undefined) updateData.allergens = data.allergens;
    if (data.caloriesPerUom !== undefined) updateData.calories_per_uom = data.caloriesPerUom;
    if (data.proteinGrams !== undefined) updateData.protein_grams = data.proteinGrams;
    if (data.fatGrams !== undefined) updateData.fat_grams = data.fatGrams;
    if (data.carbsGrams !== undefined) updateData.carbs_grams = data.carbsGrams;
    updateData.updated_at = new Date().toISOString();

    const db = trx ? (trx as Kysely<Database>) : this.db;

    const [item] = await db
      .updateTable('items')
      .set(updateData)
      .where('id', '=', itemId)
      .returningAll()
      .execute();

    if (!item) throw new Error('Failed to update item');
    return this.mapItemRecord(item);
  }

  async createCategory(data: CreateCategoryCommand): Promise<Category> {
    const [category] = await this.db
      .insertInto('categories')
      .values({
        id: uuidv4() as import('@ims/types').CategoryId,
        franchise_group_id: data.franchiseGroupId ? asFranchiseGroupId(data.franchiseGroupId) : null,
        restaurant_id: data.restaurantId ? asRestaurantId(data.restaurantId) : null,
        name: data.name,
        description: data.description ?? null,
      })
      .returningAll()
      .execute();
    if (!category) throw new Error('Failed to create category');
    return this.mapCategoryRecord(category);
  }

  async updateCategory(categoryId: string, data: UpdateCategoryDto): Promise<Category> {
    const updateData: Record<string, unknown> = {};
    if (data.name !== undefined) updateData.name = data.name;
    if (data.description !== undefined) updateData.description = data.description;
    updateData.updated_at = new Date().toISOString();

    const [category] = await this.db
      .updateTable('categories')
      .set(updateData)
      .where('id', '=', asCategoryId(categoryId))
      .returningAll()
      .execute();
    if (!category) throw new Error('Failed to update category');
    return this.mapCategoryRecord(category);
  }

  async upsertUomConversion(data: CreateUomConversionDto): Promise<UomConversion> {
    const [conversion] = await this.db
      .insertInto('uom_conversions')
      .values({
        id: uuidv4(),
        item_id: asItemId(data.itemId),
        from_uom: data.fromUom,
        to_uom: data.toUom,
        multiplier_factor: data.multiplierFactor,
      })
      .onConflict((oc) => oc
        .columns(['item_id', 'from_uom', 'to_uom'])
        .doUpdateSet({
          multiplier_factor: data.multiplierFactor,
          updated_at: new Date().toISOString()
        })
      )
      .returningAll()
      .execute();

    return {
      id: conversion.id,
      itemId: asItemId(conversion.item_id as string),
      fromUom: conversion.from_uom,
      toUom: conversion.to_uom,
      multiplierFactor: Number(conversion.multiplier_factor),
      createdAt: conversion.created_at as string,
      updatedAt: conversion.updated_at as string,
    };
  }

  async upsertItemOverride(itemId: ItemId, restaurantId: RestaurantId, data: UpdateItemOverrideDto): Promise<ItemRestaurantOverride> {
    const existing = await this.db
      .selectFrom('item_restaurant_overrides')
      .selectAll()
      .where('item_id', '=', itemId)
      .where('restaurant_id', '=', restaurantId)
      .executeTakeFirst();

    if (existing) {
      const updateData: Record<string, unknown> = { updated_at: new Date().toISOString() };
      if (data.parLevel !== undefined) updateData.par_level = data.parLevel;
      if (data.isActive !== undefined) updateData.is_active = data.isActive;

      const [updated] = await this.db
        .updateTable('item_restaurant_overrides')
        .set(updateData)
        .where('id', '=', existing.id)
        .returningAll()
        .execute();
      return this.mapOverrideRecord(updated);
    } else {
      const [inserted] = await this.db
        .insertInto('item_restaurant_overrides')
        .values({
          id: uuidv4(),
          item_id: itemId,
          restaurant_id: restaurantId,
          par_level: data.parLevel ?? 0,
          is_active: data.isActive ?? true,
        })
        .returningAll()
        .execute();
      return this.mapOverrideRecord(inserted);
    }
  }

  private mapItemRecord(row: Record<string, unknown>): Item {
    return {
      id: asItemId(row.id as string),
      franchiseGroupId: row.franchise_group_id ? asFranchiseGroupId(row.franchise_group_id as string) : null,
      restaurantId: row.restaurant_id ? asRestaurantId(row.restaurant_id as string) : null,
      categoryId: asCategoryId(row.category_id as string),
      name: row.name as string,
      sku: row.sku as string,
      type: row.type as import('@ims/types').ItemType,
      purchasingUom: row.purchasing_uom as string,
      inventoryUom: row.inventory_uom as string,
      recipeUom: row.recipe_uom as string | null,
      invToRecipeRatio: Number(row.inv_to_recipe_ratio),
      isActive: Boolean(row.is_active),
      createdAt: row.created_at as string,
      updatedAt: row.updated_at as string,
      allergens: Array.isArray(row.allergens) ? row.allergens : [],
      caloriesPerUom: Number(row.calories_per_uom || 0),
      proteinGrams: Number(row.protein_grams || 0),
      fatGrams: Number(row.fat_grams || 0),
      carbsGrams: Number(row.carbs_grams || 0),
    };
  }

  private mapCategoryRecord(row: Record<string, unknown>): Category {
    if (!row) throw new Error('Failed to map category record');
    return {
      id: asCategoryId(row.id as string),
      franchiseGroupId: row.franchise_group_id ? asFranchiseGroupId(row.franchise_group_id as string) : null,
      restaurantId: row.restaurant_id ? asRestaurantId(row.restaurant_id as string) : null,
      name: row.name as string,
      description: row.description as string | null,
      createdAt: row.created_at as string,
      updatedAt: row.updated_at as string,
    };
  }

  private mapOverrideRecord(row: Record<string, unknown>): ItemRestaurantOverride {
    if (!row) throw new Error('Failed to map override record');
    return {
      id: row.id as string,
      itemId: asItemId(row.item_id as string),
      restaurantId: asRestaurantId(row.restaurant_id as string),
      parLevel: Number(row.par_level),
      isActive: Boolean(row.is_active),
      createdAt: row.created_at as string,
      updatedAt: row.updated_at as string,
    };
  }

  async deleteItem(itemId: ItemId, trx?: unknown): Promise<void> {
    const db = trx ? (trx as Kysely<Database>) : this.db;
    await db
      .deleteFrom('items')
      .where('id', '=', itemId)
      .execute();
  }

  async deleteCategory(categoryId: string): Promise<void> {
    await this.db
      .deleteFrom('categories')
      .where('id', '=', categoryId as import('@ims/types').CategoryId)
      .execute();
  }

  async generateSku(categoryId: string): Promise<string> {
    // Get category name to derive prefix
    const category = await this.db
      .selectFrom('categories')
      .select('name')
      .where('id', '=', categoryId as import('@ims/types').CategoryId)
      .executeTakeFirst();

    const prefix = category
      ? (category.name as string)
          .toUpperCase()
          .replace(/[^A-Z0-9]/g, '')
          .substring(0, 6)
      : 'ITEM';

    // Count existing items with this category to get next sequence number
    const result = await this.db
      .selectFrom('items')
      .select((eb) => eb.fn.count<number>('id').as('count'))
      .where('category_id', '=', categoryId as import('@ims/types').CategoryId)
      .executeTakeFirst();

    const count = Number(result?.count ?? 0) + 1;
    const seq = String(count).padStart(3, '0');
    return `${prefix}-${seq}`;
  }
}

import { Injectable, NotFoundException, BadRequestException, Inject } from '@nestjs/common';
import type { ItemWithOverride, ItemId, RestaurantId, FranchiseGroupId, Item, Category, UomConversion, ItemRestaurantOverride } from '@ims/types';
import { asRestaurantId, asFranchiseGroupId } from '@ims/types';
import type { IItemWriteService, CreateItemCommand, CreateCategoryCommand } from './interfaces/i-item.service';
import { IItemRepository } from './interfaces/i-item.repository';
import { ITEM_REPOSITORY_TOKEN } from './interfaces/i-item.repository';
import type { 
  CreateItemDto, 
  UpdateItemDto, 
  CreateCategoryDto, 
  UpdateCategoryDto, 
  CreateUomConversionDto, 
  UpdateItemOverrideDto 
} from '@ims/validators';

@Injectable()
export class ItemService implements IItemWriteService {
  constructor(
    @Inject(ITEM_REPOSITORY_TOKEN) private readonly itemRepo: IItemRepository,
  ) {}

  async findById(itemId: ItemId, restaurantId: RestaurantId): Promise<ItemWithOverride> {
    const item = await this.itemRepo.findById(itemId, restaurantId);
    if (!item) {
      throw new NotFoundException(`Item ${itemId} not found for restaurant ${restaurantId}`);
    }
    return item;
  }

  async convertUom(itemId: ItemId, qty: number, fromUom: string, toUom: string): Promise<number> {
    if (fromUom === toUom) {
      return qty;
    }

    const conversion = await this.itemRepo.getUomConversion(itemId, fromUom, toUom);
    if (!conversion) {
      throw new BadRequestException(`UOM conversion not found from ${fromUom} to ${toUom} for item ${itemId}`);
    }

    return qty * conversion.multiplierFactor;
  }

  async listParLevels(restaurantId: RestaurantId, page?: number, limit?: number): Promise<{ data: ItemWithOverride[]; meta: { total: number; page: number; limit: number; totalPages: number } }> {
    return this.itemRepo.listParLevels(restaurantId, page, limit);
  }

  async createItem(
    dto: CreateItemDto,
    restaurantId: RestaurantId | null,
    franchiseGroupId: string | null,
  ): Promise<Item> {
    // Business rule: enforce item_owner_xor — exactly one owner must be set.
    // Restaurant scope takes priority when both are somehow provided.
    const resolvedRestaurantId = restaurantId ?? null;
    const resolvedFranchiseGroupId = resolvedRestaurantId ? null : (franchiseGroupId ?? null);

    if (!resolvedRestaurantId && !resolvedFranchiseGroupId) {
      throw new BadRequestException(
        'Cannot create item: authenticated user has no restaurant or franchise group context assigned.',
      );
    }

    const command: CreateItemCommand = {
      ...dto,
      restaurantId: resolvedRestaurantId,
      franchiseGroupId: resolvedFranchiseGroupId ? asFranchiseGroupId(resolvedFranchiseGroupId) : null,
    };

    return this.itemRepo.createItem(command);
  }

  async listCategories(restaurantId: RestaurantId, franchiseGroupId: string | null): Promise<Category[]> {
    return this.itemRepo.listCategories(restaurantId, franchiseGroupId);
  }

  async updateItem(itemId: ItemId, dto: UpdateItemDto, trx?: unknown): Promise<Item> {
    const updated = await this.itemRepo.updateItem(itemId, dto, trx);
    if (!updated) {
      throw new NotFoundException(`Item ${itemId} not found`);
    }
    return updated;
  }

  async createCategory(
    dto: CreateCategoryDto,
    restaurantId: RestaurantId | null,
    franchiseGroupId: string | null,
  ): Promise<Category> {
    const resolvedRestaurantId = restaurantId ?? null;
    const resolvedFranchiseGroupId = resolvedRestaurantId ? null : (franchiseGroupId ?? null);

    if (!resolvedRestaurantId && !resolvedFranchiseGroupId) {
      throw new BadRequestException(
        'Cannot create category: authenticated user has no restaurant or franchise group context assigned.',
      );
    }

    const command: CreateCategoryCommand = {
      ...dto,
      restaurantId: resolvedRestaurantId,
      franchiseGroupId: resolvedFranchiseGroupId ? asFranchiseGroupId(resolvedFranchiseGroupId) : null,
    };

    return this.itemRepo.createCategory(command);
  }

  async updateCategory(categoryId: string, dto: UpdateCategoryDto): Promise<Category> {
    const updated = await this.itemRepo.updateCategory(categoryId, dto);
    if (!updated) {
      throw new NotFoundException(`Category ${categoryId} not found`);
    }
    return updated;
  }

  async upsertUomConversion(dto: CreateUomConversionDto): Promise<UomConversion> {
    return this.itemRepo.upsertUomConversion(dto);
  }

  async updateOverride(itemId: ItemId, restaurantId: RestaurantId, dto: UpdateItemOverrideDto): Promise<ItemRestaurantOverride> {
    return this.itemRepo.upsertItemOverride(itemId, restaurantId, dto);
  }

  async deleteItem(itemId: ItemId, trx?: unknown): Promise<void> {
    await this.itemRepo.deleteItem(itemId, trx);
  }

  async deleteCategory(categoryId: string): Promise<void> {
    await this.itemRepo.deleteCategory(categoryId);
  }

  async generateSku(categoryId: string): Promise<string> {
    return this.itemRepo.generateSku(categoryId);
  }
}

import { Controller, Post, Patch, Get, Query, Body, Param, Inject, UseGuards, UseInterceptors } from '@nestjs/common';
import { SupabaseAuthGuard } from '../common/guards/supabase-auth.guard';
import { PermissionsGuard } from '../common/guards/permissions.guard';
import { RequirePermission } from '../common/decorators/require-permission.decorator';
import { TenantContextInterceptor } from '../common/interceptors/tenant-context.interceptor';
import { CurrentUser } from '../common/decorators/current-user.decorator';
import { ZodValidationPipe } from '../common/pipes/zod-validation.pipe';
import { JwtPayload, PurchaseOrderId } from '@ims/types';
import { CreatePoDto, createPoSchema, ReceivePoDto, receivePoSchema } from '@ims/validators';

import { PROCUREMENT_SERVICE_TOKEN } from './interfaces/i-procurement.service';
import type { IProcurementService } from './interfaces/i-procurement.service';

@Controller('procurement/orders')
@UseGuards(SupabaseAuthGuard, PermissionsGuard)
@UseInterceptors(TenantContextInterceptor)
export class ProcurementController {
  constructor(
    @Inject(PROCUREMENT_SERVICE_TOKEN)
    private readonly procurementService: IProcurementService,
  ) {}

  @Post()
  @RequirePermission('PROCUREMENT.WRITE')
  async createDraftPO(
